INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ordinary World the Video Game', 'This game was drawn on the Nintendo 3DS app, Flipnote. After another heartbreak Syd decides to move away from her small town to the Big City. Help her as you earn coins around Small Town by playing mini games (at the Bar, Club, and Gas Station), and by getting to know everyone in town on your Tasks list, Save coins into your piggy bank for comic book cut scenes until you''ve reached your final goal: a train ticket which you decide to Leave or Stay.' FROM games WHERE igdb_id = 336192 ON CONFLICT (game_id, language_code) DO NOTHING;
