INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meiaum-escaping-the-pix', 329373, '2025-01-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9bnd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3i5i.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MeiaUm: Escaping the Pix', 'In MeiaUm: Escaping the Pix, you dive into a digital world where precious bits are scattered across every level. Your mission? Collect them—but there''s a big risk: the Pix. One touch from this ruthless system can be fatal, and the threat is always lurking. As you progress, the challenges grow tougher, and you''ll need agility and sharp thinking to dodge the danger and grab all the bits before the Pix catches you. Every move could be your last chance.' FROM games WHERE igdb_id = 329373 ON CONFLICT (game_id, language_code) DO NOTHING;
