INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ballad of Light and Shadow', 'You were a struggling college student looking for a way out. What you found was far, far more. Plunge into the epic world of New Delphine, a kingdom awaiting its salvation at the hands of its rightful king. A sublimely, scandalously subversive dark fantasy ballad of warring brothers and the women caught in the crossfire rife with juicy plot twists and turns guaranteed to keep you on the edge of... your seat.' FROM games WHERE igdb_id = 350921 ON CONFLICT (game_id, language_code) DO NOTHING;
