INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dial 666', 'Dial 666: The Paranormal Crisis Hotline is an interactive visual novel where you take on the role of a hotline phone operator for situations dealing with monsters and supernatural beings known as aberrants. Guide your callers through tricky and often dangerous scenarios using only the information you have on hand! Chat with your coworkers, answer those phone calls, and keep people alive throughout your shift. Don''t forget, not everything is as it seems!' FROM games WHERE igdb_id = 370974 ON CONFLICT (game_id, language_code) DO NOTHING;
