INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Banished Stone', 'Embark on a unique fantasy action RPG adventure with 20 hours of gameplay. Traverse on foot, or by air, engaging in battles against monsters and bosses. Capture or kill criminals, take quests for NPCs, and acquire loot. Revive your ancestral home, befriend and tame pets, craft, or simply go fishing.' FROM games WHERE igdb_id = 290859 ON CONFLICT (game_id, language_code) DO NOTHING;
