INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Perennial Dusk: Kinsenka', 'Industry veteran Yukito Urushibara and prolific illustrator Saine join forces for the first time to craft a stunning tale about a group of young people in an eerie world of endless twilight. Follow their story as they struggle against limitless cruelty and confront the inescapable traumas of life and death together.
