INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fate And Destiny: The Elonia Chronicles', 'A heroic fantasy RPG inspired by dungeon‑crawling board games. It delivers a 15‑chapter, isometric adventure campaign where you assemble a party of six unique warriors, delve into colorful dungeons and mysterious forests, battle tactical turn‑based combat on grid‑based maps, gear up between missions, and meet a diverse cast of characters—all wrapped in a narrative shaped by your choices and culminating in multiple possible endings.' FROM games WHERE igdb_id = 350388 ON CONFLICT (game_id, language_code) DO NOTHING;
