INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slide The Tiles', 'Slide The Tiles is a simple strategy puzzle game played on a 5x5 grid. Move the red block to new spaces, and with each move, a new block appears. Create full rows or columns to clear them, earn points, and keep the board from filling up. The goal is to plan ahead, manage space carefully, and reach the highest score possible.' FROM games WHERE igdb_id = 375694 ON CONFLICT (game_id, language_code) DO NOTHING;
