INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Company', 'In Tiny Company, you are the owner of a cozy little shop that specializes in creating custom terrariums. But unlike most stores, your clients are not people — they’re the actual future inhabitants of the terrariums! From ants and beetles to snakes, geckos, mantises, snails, and more, each visitor arrives with a specific vision for their terrarium dream home, and it’s your job to bring it to life.' FROM games WHERE igdb_id = 370845 ON CONFLICT (game_id, language_code) DO NOTHING;
