INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videophobia', 'You are in a room without windows or doors. The TV dimly illuminates the room. What is this, a box? How to open it? After solving the riddle, you find the TV remote control. Click... a door appeared. You step into the darkness and hear laughter... turn around and find out what''s behind the screen.' FROM games WHERE igdb_id = 327615 ON CONFLICT (game_id, language_code) DO NOTHING;
