INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape from Mental Hospital', 'Embrace this 100 doors challenge, seek and find hidden objects and solve escape puzzles, in order to help her piece together fragments of her past. But with sinister forces determined to keep her trapped within the asylum’s walls, she must use her newfound knowledge in this adventure escape game and employ special abilities to escape 100 mental hospital doors before it’s too late. “Escape the mental hospital,” she repeats to herself, determined to break free.' FROM games WHERE igdb_id = 377217 ON CONFLICT (game_id, language_code) DO NOTHING;
