INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lewd Beach', 'Not every resort has what every tourist is looking for. But this one? It’s just perfect! Ready for some fun in the sun, a luscious MILF didn’t expect to find companionship while on vacay. And she finds the best lover she could ever have expected, a hot & sexy lifeguard to make her vacation complete!' FROM games WHERE igdb_id = 367201 ON CONFLICT (game_id, language_code) DO NOTHING;
