INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sword-of-rule', 376075, '2025-02-14', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4m2s.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword of Rule', 'Sword of Rule is a hardcore RTS battleground built for competitive players. Master the delicate balance between four critical resources (Wheat, Iron, Clay, Wood) and Gold, and maintain continuous troop training through effective resource management and raiding. Victory is defined by deep Tribal Specialization: choose Romans for absolute offensive power, Greeks for unyielding defense, or Arabs/Germans for raiding efficiency and attrition warfare. The game culminates in the massive, coordinated Wonder War, where your alliance must synchronize army movements and manage logistics 24/7 to defend the core monument to Level 100. Success demands quantitative analysis of unit stats, strategic deployment of powerful Heroes and Artifacts, and flawless coordination. Only superior strategy and alliance teamwork dictate who raises the Sword of Rule.' FROM games WHERE igdb_id = 376075 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 376075 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
