INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Classic Arcades: Pong', 'Classic Arcades: Pong brings the legendary black-and-white paddle game back with crisp visuals and tight controls. Play solo against the CPU with three difficulty levels or challenge a friend in local 2-player mode. It’s first to 11 in this pure, minimalist throwback—no frills, just fast-paced arcade action.' FROM games WHERE igdb_id = 353953 ON CONFLICT (game_id, language_code) DO NOTHING;
