INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Walker', 'So you want to become a shadow walker? In this game, you walk through a 4x4 grid of rooms, fighting your way through shadow biomes to prove your strength. During the day, you can see perfectly fine, but as night falls, your visibility is dimed, and that is when you are truly tested.' FROM games WHERE igdb_id = 291684 ON CONFLICT (game_id, language_code) DO NOTHING;
