INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truck Driver: Gold Edition', 'Get the ultimate trucking experience with Truck Driver: Gold Edition! This definitive edition includes the Truck Driver base game, the Heading North DLC, additional paint jobs inspired by the USA, UK, Germany, and France, and the Hidden Places & Damage System DLC. Plus, enjoy enhanced visuals and performance, including faster loading times, improved frame rates, extended draw distance, enhanced reflections, increased world density, a smoother day-night cycle, and more!' FROM games WHERE igdb_id = 340844 ON CONFLICT (game_id, language_code) DO NOTHING;
