INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Sheep', 'Get ready to fluff your brain and relax your heart, because this little sheep in a top hat is about to turn puzzle-solving into the cutest ritual of calm you’ve ever seen. Magic Sheep is a charming, slow-paced puzzle adventure where you push wooden barrels across peaceful gardens until each one rests perfectly on a marble pedestal. No pressure, no timer, only soft music, gentle thinking, and plenty of “oh, that was clever” moments.' FROM games WHERE igdb_id = 380397 ON CONFLICT (game_id, language_code) DO NOTHING;
