INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knight On The Moon', 'This is a top down adventure game involving exploration, delving into dungeons, solving puzzles, and engaging in combat with various enemies. Players control a protagonist who must gather items, such as weapons, tools, and upgrades, to progress through increasingly challenging areas. Exploration and discovery are key, as players uncover hidden secrets, navigate mazes, and complete objectives to advance the story. This game is a balance of action, problem-solving.' FROM games WHERE igdb_id = 350621 ON CONFLICT (game_id, language_code) DO NOTHING;
