INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sheep Running', 'In this charming and challenging game, you play as a shepherd with a critical mission — guide your flock safely into the barn without letting any sheep fall off cliffs or drown in the water. Use fear wisely to steer the sheep, but be careful — push them too hard, and they might panic and run to their doom! The more sheep you safely herd into the barn, the higher your score. Master the delicate balance between control and chaos in this fun and strategic herding adventure!' FROM games WHERE igdb_id = 347039 ON CONFLICT (game_id, language_code) DO NOTHING;
