INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farmer Fowl''s Farmhouse', 'Step inside the abandoned Farmer Fowl''s Farmhouse — once a cheerful children''s attraction, now left to rot since it''s sudden closure decades prior. You play as Eli, a salvage assessor sent to document and mark the building''s remaining assets before demolition. You must mark items for salvage, take photos of rooms, and collect leftover documents. However something evil still lurks within the building, can you complete your job and get out of the building? Or become a part of its tragic history.' FROM games WHERE igdb_id = 375639 ON CONFLICT (game_id, language_code) DO NOTHING;
