INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Primal Dinosaur Shooter: Dino Killer', 'Primal Dinosaur Shooter: Dino Killer throws you into an era where dinosaurs once again rule the land. In a hostile environment, you are the last hope to restore balance. Armed with modern weapons and unshakable determination, you face a relentless battle against prehistoric creatures that hunt without mercy. Every step could be your last, and survival depends solely on you.' FROM games WHERE igdb_id = 374672 ON CONFLICT (game_id, language_code) DO NOTHING;
