INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capsule Hero', 'This is a minimalist challenge game based on a physics engine. Players control a capsule-shaped character, keep balance on a narrow wooden board, and rely on skills and patience to gradually walk out of the dark room. Every step is a challenge, and every failure will bring great frustration.' FROM games WHERE igdb_id = 353611 ON CONFLICT (game_id, language_code) DO NOTHING;
