INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Waifu by Myside: Patch Me In', 'A simple erotic visual novel — right up until the moment you launch it. Your dream waifu suddenly starts acting strange: watching you too closely, hiding something she shouldn’t. Now you must uncover what happened to the game — and what Candy is truly planning…' FROM games WHERE igdb_id = 384718 ON CONFLICT (game_id, language_code) DO NOTHING;
