INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rise of Fearless', 'Rise of Fearless is the first full-scale African-inspired battle royale game, designed to bring African history, culture, and landmarks into competitive gaming. It features large-scale battles where players fight for survival, using strategy, skill, and teamwork. The game’s setting draws inspiration from Africa’s rich heritage, including real-world landmarks like the Great Rift Valley and Lalibela’s rock-hewn churches.' FROM games WHERE igdb_id = 345218 ON CONFLICT (game_id, language_code) DO NOTHING;
