INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Archer', 'Embark on an epic adventure in Tiny Archer, a breathtaking 2D platformer set in a dangerous, slime-infested dungeon! As a nimble archer, fight through 20 treacherous levels filled with cunning slimes, each requiring clever tactics to defeat. Master wall-jumping to navigate deadly traps, collect crystals, and grab powerful quivers that unleash triple-shot barrages of devastating power. With precise controls and diverse enemies, Tiny Archer offers thrilling combat and exploration.' FROM games WHERE igdb_id = 379300 ON CONFLICT (game_id, language_code) DO NOTHING;
