INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poultry Party', 'Poultry Party is a 2D arcade-like action game that gets harder as you go. Dodge, jump over, and extinguish hazards to avoid becoming dinner. Need help? Add up to 17 additional players (yes really) to assist you. Survive as long as you can, or beat the game as fast as you can. The choice is yours!' FROM games WHERE igdb_id = 341558 ON CONFLICT (game_id, language_code) DO NOTHING;
