INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('revenge-on-gold-diggers', 372482, '2025-06-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coanjs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4eyq.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Revenge On Gold Diggers', 'The first-ever FMV game about emotional fraud, brought to life by Chinese director Hu Yaohui and a team of film industry veterans. In this entirely fictional story, step into the role of a hunter of hearts and infiltrate a shadowy organization deep in emotional deceit. In this immersive, third-person cinematic experience, every choice matters as you navigate a treacherous web of lies, seduction, and manipulation. The game features 472 minutes of cinematic footage, over 200 choices, and 38 possible endings. You can also explore the Love Dossier with over 140,000 words, and interact with others on the Wall of Memories, which already contains more than 4,000 player comments.' FROM games WHERE igdb_id = 372482 ON CONFLICT (game_id, language_code) DO NOTHING;
