INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubbles in the Air', 'Bubbles in the Air is a grid-free real-time matching game. In a dog''s dream, colorful soap bubbles float and collide… The task is simple! Shoot bubbles, merge matching ones, and let them burst—creating even more bubbles. Can you make it to the end of the dream?' FROM games WHERE igdb_id = 347093 ON CONFLICT (game_id, language_code) DO NOTHING;
