INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Crawling Dead', 'The Crawling Dead is a strategy simulation game where you take on the role of a lead scientist tasked with saving Stormveil National Park from ecological collapse. Swarms of invasive insects are devastating the park’s delicate ecosystems, and traditional methods of pest control have failed. Your solution? Genetically engineered parasitoid wasps. Harmless to humans, these beneficial wasps are killers of pest insects and utilize a variety of creepy strategies to manipulate and kill their hosts - turning them into The Crawling Dead!' FROM games WHERE igdb_id = 358799 ON CONFLICT (game_id, language_code) DO NOTHING;
