INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Argonauts Agency: Gorgon Medusa - Collector''s Edition', 'Jason and Medea are on a mission again: the famous relic collector Pelias asked them to retrieve the artifact that protects against Medusa''s gaze. Without hesitation, the Argonauts set off on a journey to recover the artifact, save the cursed people, and find new friends. Explore the world, gather resources, and help the heroes lift the curse, using your time management skills and strategy to stop the curse and defeat the evil!
