INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baggage Handler Simulator', 'BH Simulator is a fun and immersive airport logistics game. As a baggage hub manager, build efficient conveyor systems to sort, unload, and load luggage. Plan smart routes, avoid bottlenecks, and prove you''re the boss of the baggage game. Can you turn chaos into perfect order?' FROM games WHERE igdb_id = 364772 ON CONFLICT (game_id, language_code) DO NOTHING;
