INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atomanta', 'In Atomanta, you step into the role of Taria Takara, a space pirate on a mission to recover a highly valuable artifact hidden on the planet Azavuraz. Armed with the powerful Atomic Manta warship, Taria finally has a chance to claim the bounty and pay off the debts from her previous handlers.' FROM games WHERE igdb_id = 365222 ON CONFLICT (game_id, language_code) DO NOTHING;
