INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Loop Below', 'Trapped in a looping, claustrophobic bunker, you must detect subtle anomalies before they consume you. Watch every shadow. Memorize every detail. No weapons. No escape. Just your scanner, your instincts — and the creeping dread that something is terribly wrong.' FROM games WHERE igdb_id = 366069 ON CONFLICT (game_id, language_code) DO NOTHING;
