INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goblin Village', 'Goblin Village is a cozy, roguelike, unlockathon with 2 to 10 minute runs. Choose your leader, and set off to establish your settlement. Manage your resources and food via your 3 daily actions. End your day by paying taxes and feeding your tribe. Taxes go up daily! After this, a random end of day event occurs. The game has over 1,000 events!' FROM games WHERE igdb_id = 353718 ON CONFLICT (game_id, language_code) DO NOTHING;
