INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Almania', 'The free game accompanying the third season of the German TV series Almania. The plays joins the school as a new student. They walk around, follow quests, build items in the school, upgrade rooms, harvest items and virtual currency with the overall goal of having a nice school function. The game is as a humorous, story-driven simulation.' FROM games WHERE igdb_id = 377971 ON CONFLICT (game_id, language_code) DO NOTHING;
