INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taria & Como', 'Taria & Como is a physics-based puzzle platformer where movement is built around swinging instead of jumping. Play as Taria, a young girl with a prosthetic leg, as she rescues her little sister Como in the midst of a world that constantly underestimates her. Separated after a disaster, Taria wakes up in a hospital where she’s forced to use an “approved” prosthetic that limits her mobility. Undeterred, she takes control of her own fate, using ingenuity and sheer determination to escape and find her sister.' FROM games WHERE igdb_id = 340849 ON CONFLICT (game_id, language_code) DO NOTHING;
