INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NMO: No More Operators', 'NMO is a thrilling multiplayer (5 vs 1) game where one player, the Ox, lurks in the shadows to deceive and neutralize the Operators, while others take on the role of Operators, working independently or cooperatively to identify and eliminate the Ox hidden among them.' FROM games WHERE igdb_id = 294341 ON CONFLICT (game_id, language_code) DO NOTHING;
