INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Floor 13', 'In Floor13, reality doesn’t change all at once — it shifts quietly, waiting for you to notice.You walk the same office corridor over and over, but something always feels… slightly off.Your task is simple: observe, detect, report. If you fail to see the difference, the corridor will keep you forever.' FROM games WHERE igdb_id = 377578 ON CONFLICT (game_id, language_code) DO NOTHING;
