INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Rush', 'DEAD RUSH - This is a dynamic first-person shooter in which you must confront hordes of hungry zombies! There''s no convoluted plot, side quests and a large open world. Here you will find only concentrated action. The only thing you will be doing in this game is shooting at the crowd of reanimated dead. Explore the location, find the most powerful gun and destroy ten waves of zombies before they reach you!' FROM games WHERE igdb_id = 327277 ON CONFLICT (game_id, language_code) DO NOTHING;
