INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mask of Dead II: Shadow Of Pelagius', 'Mask of Dead 2: Shadow of Pelagius is a JRPG with an active combat system. A lot of time has passed since the first Adamant War the reapers were able to recover from the damage they received and restore Purgatory, but not for long... Riom Ruri, the son of the High Reaper, has just finished training and has already received his first task - to scout the surrounding area with a small squad of other reapers. But everything does not go according to plan and Riom is forced to face the mistakes of his brothers in the past and save Purgatory from complete destruction.' FROM games WHERE igdb_id = 334646 ON CONFLICT (game_id, language_code) DO NOTHING;
