INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bacrush', 'Bacrush is a fast-paced arcade game where you control a small green square. Your goal is to collect as many coins as possible while dodging dangerous gray cubes. You can shoot projectiles to push back the cubes, but be careful — shooting too much will cause your square to overheat! Gather as many coins as you can and survive as long as possible to set a new high score.' FROM games WHERE igdb_id = 347038 ON CONFLICT (game_id, language_code) DO NOTHING;
