INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vyzyvatel', 'Vyzyvatel is a fast and fair trivia game from the Czech Republic, where knowledge matters more than luck. Play with 2–5 players and find out who knows the most. Questions are created by the community, making the game constantly grow and stay fresh. No pay-to-win, just pure competition and fun. Take on the challenge and become the ultimate Vyzyvatel.' FROM games WHERE igdb_id = 374717 ON CONFLICT (game_id, language_code) DO NOTHING;
